-- ============================================================================
-- CATALOGUE : place les annonces Immobilier (module Immobilier) + Location (NEXUS
-- Location) sur le site, ATTRIBUEES AU COMPTE ADMIN (vendor_id = admin). Le nom de
-- l'agence reste dans products.vendor_name, et le contact (annonceur + telephone) est
-- conserve dans les specs. Prix en EUR (FCFA / 655.957). Idempotent (skip si present).
-- ============================================================================

-- Garde-fou : il faut un compte admin.
do $$ begin
  if not exists (select 1 from public.profiles where role='admin') then
    raise exception 'Aucun compte admin (profiles.role=admin) — impossible d''attribuer les annonces.';
  end if;
end $$;

drop table if exists _annonces;
create temp table _annonces(name text, category text, price_eur numeric, description text, image_url text, vendor_name text, is_rental bool, rental_specs jsonb, is_realestate bool, realestate_specs jsonb);

-- Attribution a l'admin (le plus ancien si plusieurs).
with adm as (select id from public.profiles where role='admin' order by created_at asc limit 1)
select an.name,an.category,an.price_eur,1,an.description,an.image_url,(select id from adm),an.vendor_name,true,an.is_rental,an.rental_specs,an.is_realestate,an.realestate_specs
  from _annonces an
 where not exists (select 1 from public.products p where p.vendor_id=(select id from adm) and p.name=an.name
     and coalesce(p.is_rental,false)=an.is_rental and coalesce(p.is_realestate,false)=an.is_realestate);

-- Recap.
select 'immobilier' as module, count(*) as annonces from _annonces where is_realestate
 union all select 'location', count(*) from _annonces where is_rental;
